// Generates lib/generated/data-index.ts so that adding a recipe or device is just "drop a JSON file in data/".
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const list = (dir) =>
  fs.readdirSync(path.join(root, dir)).filter((f) => f.endsWith(".json")).sort();

const recipes = list("data/recipes");
const devices = list("data/devices");
const ident = (prefix, f) => prefix + f.replace(/\.json$/, "").replace(/[^a-zA-Z0-9]/g, "_");

const lines = [
  "// AUTO-GENERATED by scripts/gen-data-index.mjs — do not edit. Add JSON files to data/ instead.",
  ...recipes.map((f) => `import ${ident("r_", f)} from "@/data/recipes/${f}";`),
  ...devices.map((f) => `import ${ident("d_", f)} from "@/data/devices/${f}";`),
  "",
  `export const rawRecipes: Record<string, unknown> = {\n${recipes.map((f) => `  "${f}": ${ident("r_", f)},`).join("\n")}\n};`,
  `export const rawDevices: Record<string, unknown> = {\n${devices.map((f) => `  "${f}": ${ident("d_", f)},`).join("\n")}\n};`,
  "",
];
fs.mkdirSync(path.join(root, "lib/generated"), { recursive: true });
fs.writeFileSync(path.join(root, "lib/generated/data-index.ts"), lines.join("\n"));
console.log(`data index: ${recipes.length} recipes, ${devices.length} devices`);
